    "htop",
    "id",
    "info",
    "iostat",
    "join",
    "ldd",
    "less",
    "ls",
    "lsof",
    "man",
    "more",
    "mount",
    "netstat",
    "nl",
    "nm",
    "nslookup",
    "objdump",
    "od",
    "paste",
    "ping",
