                    // `archive` to stdout only; forbid writing a file or hitting a remote.
                    "archive" => {
                        let forbidden_flags = ["--output", "-o", "--remote"];
                        if argv.iter().any(|a| forbidden_flags.contains(&a.as_str())) {
